import { useEffect, useRef } from 'react';

/**
 * 场地页首次引导（两步）：光圈钉住当前步骤的目标，点任意处推进。
 *
 * 为什么用 rAF 直接写 style 而不是每帧 setState：场地里的设备标记随进场动画、自动旋转一直在动，
 * 用 state 每帧重渲染整张页面代价太大；这里只改两个绝对定位元素的 transform 与尺寸，不碰 React 树。
 * 视觉与地图页引导同一套语言（纸白卡片 + 青绿光圈 + 呼吸动画），只换位置由谁算。
 */
export interface SiteGuideStep {
  /** marker：场上的设备标记（取离画面中心最近的一颗，保证它在视野里）；tools：右上角工具条 */
  target: 'marker' | 'tools';
  title: string;
  hint?: string;
}

const HALO_PAD = 8; // 光圈比目标外扩的像素
const CARD_GAP = 14; // 卡片与目标之间的空隙
const CARD_EDGE = 10; // 卡片离舞台边缘的最小留白
const HALO_EDGE = 2; // 光圈也夹进舞台：标记贴着屏边时，宁可光圈略偏一点，也不要缺一个角
const TAP_SLOP = 6; // 位移不超过这些像素才算「点任意处」，拖动转视角不推进
const SETTLE_FRAMES = 3; // 目标连续多少帧基本不动才把光圈亮出来
const SETTLE_TIMEOUT_MS = 3000; // 一直动（自动旋转开着）时的兜底：等这么久就先亮
const EDGE_INSET = 8; // 判定「整个框都在舞台里」的边距：挑标记时优先要它，免得光圈出屏
const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

interface SiteGuideProps {
  /** 量测基准元素（`.site-studio`）：光圈与卡片都相对它定位 */
  host: React.RefObject<HTMLElement | null>;
  step: number;
  steps: SiteGuideStep[];
  onAdvance(): void;
  /** 立即收起引导（Escape 与右上角「结束导览」走这条路）：多步引导里不该把剩下的步骤走完再关。 */
  onClose(): void;
}

export function SiteGuide({ host, step, steps, onAdvance, onClose }: SiteGuideProps) {
  const haloRef = useRef<HTMLSpanElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const caretRef = useRef<HTMLSpanElement>(null);
  const targetRef = useRef<HTMLElement | null>(null);
  const tapRef = useRef<{ x: number; y: number } | null>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  /* 打开引导的那颗元素（「?」圆钮，或自动弹出时的 body）。卸载时把焦点还给它——
     这块浮层是整屏 aria-modal，焦点留在里面等于键盘用户被关在里头（参考 ResourceDrawer 的 openerRef）。
     惰性初值只在首次渲染求值一次：本组件活得和一次引导一样长，effect 重建不该重新记锚点。 */
  const openerRef = useRef<HTMLElement | null>(document.activeElement instanceof HTMLElement ? document.activeElement : null);
  const current = steps[step];
  const isLast = step === steps.length - 1;

  /* 浮层挂载即进入：把焦点放到浮层本体上，读屏才会念出 dialog 的名字，键盘也才有落点。
     同时盯住 focusin：焦点一旦落到浮层外就被拽回来（整屏 aria-modal 的 Tab 环路）。
     为什么不用 keydown 判 Tab 端点：真浏览器与 `user-event` 都在 keydown 之前就把焦点挪走了
     （React 回调里 `event.defaultPrevented` 已经是 true），抢不过；盯 focusin 与顺序无关。
     卸载时把焦点还给打开者——body 不算"打开者"（首次自动弹出时它只能是 body，给 body 调 focus 是空操作）。 */
  useEffect(() => {
    const overlay = overlayRef.current;
    if (!overlay) return;
    overlay.focus();
    const trapFocus = (event: FocusEvent) => {
      const target = event.target;
      if (target instanceof Node && overlay.contains(target)) return;
      const next = overlay.querySelector<HTMLElement>(FOCUSABLE) ?? overlay;
      next.focus();
    };
    document.addEventListener('focusin', trapFocus);
    return () => {
      document.removeEventListener('focusin', trapFocus);
      const opener = openerRef.current;
      if (opener && opener !== document.body && opener.isConnected) opener.focus();
    };
  }, []);

  /* 键盘动作分成两条路，别混：
     方向键/回车/空格 = "再走一步"（onAdvance，SitePage 把 step +1）；
     Escape = "立即结束"（onClose，SitePage 直接把 step 推到末尾收起浮层并记 seen）。
     早先 Escape 走的是 onAdvance，多步引导里按一下只是跳到下一步，要按到越界才收起——
     用户按 Esc 的期待是退出，不是"继续"。 */
  const advance = () => { if (current) onAdvance(); };
  const finish = onClose;

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      finish();
      return;
    }
    if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowRight') {
      event.preventDefault();
      advance();
      return;
    }
    if (event.key !== 'Tab') return;
    /* Tab 环路：端点对折。环里必须把浮层这个 tabindex={-1} 的容器也算上——
       卡片里只有「结束导览」一枚可聚焦元素，没有容器做端点的话就没得环。
       两个注意点：
       ① 端点判断看 document.activeElement、而不是 `!event.defaultPrevented`：真浏览器与 `user-event`
          都在 keydown 之前就把焦点挪走了（React 回调里 `event.defaultPrevented` 已经是 true），抢不过；
       ② 焦点已经被挪出浮层时也按"端点"处理，直接拽回来（下面还有一层 focusin 兜底）。 */
    const overlay = overlayRef.current;
    if (!overlay) return;
    const ring = [overlay, ...overlay.querySelectorAll<HTMLElement>(FOCUSABLE)]
      .filter(element => !element.hasAttribute('disabled'));
    const first = ring[0];
    const last = ring[ring.length - 1];
    if (!first || !last) return;
    const active = document.activeElement;
    const escaped = !(active instanceof Node) || !overlay.contains(active);
    if (event.shiftKey ? (active === first || escaped) : (active === last || escaped)) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  };

  // 换一步就丢掉上一个目标，交给下面的循环重新找（下一步的目标可能还没渲染出来）。
  useEffect(() => {
    targetRef.current = null;
  }, [current]);

  useEffect(() => {
    let frame = 0;
    let lastKey = '';
    let settleCount = 0;
    let settledRect: DOMRect | null = null;
    const startedAt = performance.now();

    /* 标记几乎贴在画面边缘时，光圈也会跟着出屏——所以先挑「整个框都在舞台里」的那些，
       一个都没有（场地很宽、手机很窄）才退回「离画面中心最近」。 */
    const insideHost = (rect: DOMRect, rootRect: DOMRect) => (
      rect.left >= rootRect.left + EDGE_INSET
      && rect.right <= rootRect.right - EDGE_INSET
      && rect.top >= rootRect.top + EDGE_INSET
      && rect.bottom <= rootRect.bottom - EDGE_INSET
    );

    const pickMarker = (root: HTMLElement, rootRect: DOMRect): HTMLElement | null => {
      const boxes = Array.from(root.querySelectorAll<HTMLElement>('.site-marker'))
        .map(node => ({ node, rect: node.getBoundingClientRect() }))
        .filter(item => item.rect.width > 0 && item.rect.height > 0);
      if (boxes.length === 0) return null;
      const roomy = boxes.filter(item => insideHost(item.rect, rootRect));
      const pool = roomy.length > 0 ? roomy : boxes;
      const centerX = rootRect.left + rootRect.width / 2;
      const centerY = rootRect.top + rootRect.height / 2;
      let best: { node: HTMLElement; distance: number } | null = null;
      for (const item of pool) {
        const distance = Math.hypot(item.rect.left + item.rect.width / 2 - centerX, item.rect.top + item.rect.height / 2 - centerY);
        if (!best || distance < best.distance) best = { node: item.node, distance };
      }
      return best?.node ?? null;
    };

    /* 目标在场景转动中可能滑出画面：只要它整个框还在舞台里就继续跟着（不来回跳），
       滑出去了才重新挑一颗。 */
    const resolveTarget = (root: HTMLElement, rootRect: DOMRect): HTMLElement | null => {
      if (!current) return null;
      if (current.target === 'tools') {
        const tools = targetRef.current?.isConnected ? targetRef.current : root.querySelector<HTMLElement>('.site-tools');
        return tools;
      }
      const rect = targetRef.current?.isConnected ? targetRef.current.getBoundingClientRect() : null;
      if (rect && rect.width > 0 && rect.height > 0 && insideHost(rect, rootRect)) return targetRef.current;
      return pickMarker(root, rootRect) ?? (targetRef.current?.isConnected ? targetRef.current : null);
    };

    const tick = () => {
      frame = window.requestAnimationFrame(tick);
      const root = host.current;
      const halo = haloRef.current;
      const card = cardRef.current;
      if (!root || !halo || !card || !current) return;

      const hide = () => {
        if (lastKey === 'hidden') return;
        halo.style.opacity = '0';
        card.style.opacity = '0';
        lastKey = 'hidden';
      };

      const rootRect = root.getBoundingClientRect();
      const target = resolveTarget(root, rootRect);
      targetRef.current = target;
      const targetRect = target?.getBoundingClientRect();
      if (!targetRect || targetRect.width <= 0 || targetRect.height <= 0) {
        settleCount = 0;
        settledRect = null;
        hide();
        return;
      }

      /* 进场动画期间标记一直在动，那会儿量出来的位置下一帧就过期（光圈会跟到屏外、还来回跳）。
         所以要求目标矩形连续几帧基本不动再亮出来；一直动（开了自动旋转）就 SETTLE_TIMEOUT_MS 兜底。 */
      const still = settledRect !== null
        && Math.abs(targetRect.left - settledRect.left) < 1
        && Math.abs(targetRect.top - settledRect.top) < 1
        && Math.abs(targetRect.width - settledRect.width) < 1;
      settleCount = still ? settleCount + 1 : 0;
      settledRect = targetRect;
      if (settleCount < SETTLE_FRAMES && performance.now() - startedAt < SETTLE_TIMEOUT_MS) {
        hide();
        return;
      }

      const left = targetRect.left - rootRect.left;
      const top = targetRect.top - rootRect.top;
      const cardRect = card.getBoundingClientRect();
      // 卡片优先放目标下方；下方放不下就翻到上方，再夹进舞台内（与标记气泡同一套「最小位移」思路）。
      const below = top + targetRect.height + CARD_GAP;
      const cardBelow = below + cardRect.height + CARD_EDGE <= rootRect.height;
      const cardTop = cardBelow ? below : Math.max(CARD_EDGE, top - CARD_GAP - cardRect.height);
      const centerX = left + targetRect.width / 2;
      const cardLeft = Math.min(
        Math.max(centerX - cardRect.width / 2, CARD_EDGE),
        Math.max(CARD_EDGE, rootRect.width - cardRect.width - CARD_EDGE),
      );
      const caretX = Math.min(Math.max(centerX - cardLeft, 16), Math.max(16, cardRect.width - 16));

      const key = `${left},${top},${targetRect.width},${targetRect.height},${cardLeft},${cardTop},${caretX}`;
      if (key === lastKey) return;
      lastKey = key;

      // 光圈也夹在舞台内：窄屏上院区会铺满整幅，最边上的标记必然压边，
      // 这时候把光圈拉回来 2px，看起来仍是照着它的框，但不会缺一个角。
      const haloLeft = Math.max(left - HALO_PAD, HALO_EDGE);
      const haloTop = Math.max(top - HALO_PAD, HALO_EDGE);
      const haloRight = Math.max(haloLeft + 16, Math.min(left + targetRect.width + HALO_PAD, rootRect.width - HALO_EDGE));
      const haloBottom = Math.max(haloTop + 16, Math.min(top + targetRect.height + HALO_PAD, rootRect.height - HALO_EDGE));
      halo.style.transform = `translate3d(${haloLeft}px, ${haloTop}px, 0)`;
      halo.style.width = `${haloRight - haloLeft}px`;
      halo.style.height = `${haloBottom - haloTop}px`;
      halo.style.opacity = '1';
      card.style.transform = `translate3d(${cardLeft}px, ${cardTop}px, 0)`;
      card.style.opacity = '1';
      card.dataset.place = cardBelow ? 'below' : 'above';
      if (caretRef.current) caretRef.current.style.left = `${caretX}px`;
    };

    frame = window.requestAnimationFrame(tick);
    return () => window.cancelAnimationFrame(frame);
  }, [host, current]);

  if (!current) return null;

  return (
    <div
      className="site-guide"
      data-testid="site-guide"
      role="dialog"
      aria-modal="true"
      aria-label="场地导览"
      tabIndex={-1}
      ref={overlayRef}
      onKeyDown={handleKeyDown}
      onPointerDown={event => { tapRef.current = { x: event.clientX, y: event.clientY }; }}
      onPointerUp={event => {
        const tap = tapRef.current;
        tapRef.current = null;
        // 拖动转视角的那一下不算「点」：位移超过阈值就只当手势，不推进。
        if (tap && Math.hypot(event.clientX - tap.x, event.clientY - tap.y) > TAP_SLOP) return;
        onAdvance();
      }}
      onPointerCancel={() => { tapRef.current = null; }}
    >
      <span className="site-guide-halo" aria-hidden="true" ref={haloRef} />
      <div className="site-guide-card" role="note" data-testid={`site-guide-step-${step}`} ref={cardRef}>
        <strong>{current.title}</strong>
        {current.hint ? <span>{current.hint}</span> : null}
        {/* 文案一个字没动：手势语义保持"点任意处"。这枚按钮是给键盘/读屏用户的那条等价路径，
            所以它的名字写成"结束导览"（Escape 做的事），而不是"继续"——继续在浮层本身上按回车/空格即可。 */}
        <button
          type="button"
          className="site-guide-end"
          aria-label="结束导览"
          onPointerDown={event => event.stopPropagation()}
          onPointerUp={event => event.stopPropagation()}
          onKeyDown={event => {
            // 按钮自己处理回车/空格：挡住冒泡，免得按钮的 click 与浮层的 keydown 各推进一次。
            if (event.key === 'Enter' || event.key === ' ') event.stopPropagation();
          }}
          onClick={finish}
        >
          ×
        </button>
        <em>{`第 ${step + 1}/${steps.length} 步 · 点任意处继续${
          isLast ? ' · 「?」可重看' : ''
        }`}</em>
        <span className="site-guide-caret" aria-hidden="true" ref={caretRef} />
      </div>
    </div>
  );
}
